class C
{
    bool M0(int x) => true;

    void M1(bool b)
    {
        int x;
        _ = (b && M0(x = 0) ? true : false)
            ? x.ToString()
            : x.ToString(); // 1
    }

    void M2(bool b)
    {
        int x;
        _ = (b && M0(x = 0) ? false : true)
            ? x.ToString() // 2
            : x.ToString();
    }

    void M3(bool b)
    {
        int x;
        _ = (b || M0(x = 0) ? true : false)
            ? x.ToString() // 3
            : x.ToString();
    }

    void M4(bool b)
    {
        int x;
        _ = (b || M0(x = 0) ? false : true)
            ? x.ToString()
            : x.ToString(); // 4
    }
}

